// Cross-repo contract: the landing against the CMS's real response.
//
// __golden__/christmas-2026.golden.json is GENERATED by the CMS repo
// (CMS_management- src/features/campaigns/campaigns.integration.test.ts) from
// the real /api/v1/campaigns routes over the migrated seed, for vi and en. This
// file proves the landing parses that exact response and renders the navbar
// pill, mega-menu, home banner and campaign pages from it, through the real
// cmsClient (only `fetch` is stubbed).
//
// Refreshing the golden — never edit it by hand:
//   1. In the CMS repo: UPDATE_GOLDEN=1 bun test src/features/campaigns/campaigns.integration.test.ts
//   2. Copy src/features/campaigns/__golden__/christmas-2026.golden.json from
//      the CMS repo byte-for-byte to src/lib/__golden__/ here.
//   3. bun run test. A failure here after a refresh is real CMS ↔ landing drift:
//      fix the parser/components (or the CMS) rather than the expectations.
// Expected labels and hrefs below are written from the contract
// (runs/xmas-campaigns-20261024/contract.md § Seed), not read from the golden.

import { cleanup, fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { HelmetProvider } from "react-helmet-async";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import { useEffect, type ReactNode } from "react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import Navbar from "@/components/Navbar";
import { CampaignHomeBanner } from "@/components/campaigns/CampaignHomeBanner";
import CampaignsPage from "@/pages/campaigns/CampaignsPage";
import CampaignDetailPage from "@/pages/campaigns/CampaignDetailPage";
import { I18nProvider, useI18n } from "@/lib/i18n";
import { campaignResponseSchema, campaignsResponseSchema } from "./campaigns";
import fixture from "./campaigns.fixture.json";
import golden from "./__golden__/christmas-2026.golden.json";

vi.mock("@/components/lead/LeadFormDialog", () => ({ LeadFormDialog: () => null }));
vi.mock("@/components/ScrollReveal", () => ({ default: ({ children }: { children: ReactNode }) => <>{children}</> }));

type Lang = "vi" | "en";

// Contract § Seed: menu hrefs in order, without the language prefix.
const SEED_HREFS = [
  "/catalog/christmas",
  "/catalog/best-seller",
  "/catalog/new-arrivals",
  "/christmas#san-pham",
  "/christmas#san-pham",
  "/christmas#san-pham",
  "/christmas#hot",
  "/christmas#san-pham",
];

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });

/** The CMS boundary: serve the golden by URL; everything else is offline. */
function serveGolden() {
  return vi.spyOn(globalThis, "fetch").mockImplementation(async (input) => {
    const url = new URL(String(input));
    const lang = (url.searchParams.get("lang") ?? "vi") as Lang;
    if (url.pathname.endsWith("/campaigns")) return json(golden.list[lang]);
    if (url.pathname.endsWith("/campaigns/christmas-2026")) return json(golden.detail[lang]);
    if (url.pathname.endsWith("/translations")) return json({ locale: lang, translations: {} });
    throw new TypeError(`offline: ${url.pathname}`);
  });
}

function SetLang({ lang, children }: Readonly<{ lang: Lang; children: ReactNode }>) {
  const { language, setLanguage } = useI18n();
  useEffect(() => setLanguage(lang), [lang, setLanguage]);
  return language === lang ? <>{children}</> : null;
}

function mount(ui: ReactNode, lang: Lang, path: string) {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  return render(
    <QueryClientProvider client={client}>
      <HelmetProvider>
        <I18nProvider>
          <SetLang lang={lang}>
            <MemoryRouter initialEntries={[path]}>{ui}</MemoryRouter>
          </SetLang>
        </I18nProvider>
      </HelmetProvider>
    </QueryClientProvider>,
  );
}

beforeEach(() => {
  serveGolden();
});
afterEach(() => {
  cleanup();
  vi.restoreAllMocks();
});

describe("golden: the landing parser understands the CMS response", () => {
  it.each(["vi", "en"] as const)("%s list and detail parse without losing or defaulting any field", (lang) => {
    // Equality after parsing means: every field the CMS sends is one the
    // landing schema knows (zod would strip unknown ones) and none is missing.
    expect(campaignsResponseSchema.parse(golden.list[lang])).toEqual(golden.list[lang]);
    expect(campaignResponseSchema.parse(golden.detail[lang])).toEqual(golden.detail[lang]);
  });

  it("the hand-written fixture's Christmas entry still matches what the CMS serves", () => {
    expect(fixture.campaigns[0]).toEqual(golden.list.vi.campaigns[0]);
  });
});

describe("golden: navbar pill and mega-menu", () => {
  it.each([
    ["vi", "Christmas Collection", "Fulfill tại Mỹ", "Khám phá bộ sưu tập"],
    ["en", "Christmas Collection", "US Fulfillment", "Explore Collection"],
  ] as const)("%s: the pill links to the lang-prefixed /christmas and every menu item keeps the prefix", async (lang, first, fourth, cta) => {
    mount(<Navbar />, lang, `/${lang}`);
    const pill = await screen.findByRole("link", { name: /Christmas\s*NEW/ });
    expect(pill).toHaveAttribute("href", `/${lang}/christmas`);

    fireEvent.focus(pill);
    expect(pill).toHaveAttribute("aria-expanded", "true");
    const panel = document.getElementById("campaign-mega-menu") as HTMLElement;
    const menu = within(panel).getByRole("navigation");
    const links = within(menu).getAllByRole("link");
    expect(links.map((a) => a.getAttribute("href"))).toEqual(SEED_HREFS.map((h) => `/${lang}${h}`));
    expect(links[0]).toHaveTextContent(first);
    expect(links[3]).toHaveTextContent(fourth);
    expect(within(panel).getByRole("link", { name: new RegExp(cta) })).toHaveAttribute("href", `/${lang}/christmas`);
  });
});

describe("golden: home banner", () => {
  it.each([
    ["vi", "Khám phá bộ sưu tập", "Sản phẩm POD sẵn sàng cho mùa lễ"],
    ["en", "Explore Collection", "POD products ready for the holiday season"],
  ] as const)("%s: shows the seeded campaign with its CTA, dates and prefixed menu cards", async (lang, cta, summary) => {
    mount(<CampaignHomeBanner />, lang, `/${lang}`);
    const banner = await screen.findByRole("region", { name: "Christmas 2026 Collection" });
    expect(banner).toHaveTextContent(summary);
    expect(banner).toHaveTextContent("24/10/2026 – 25/12/2026");
    expect(within(banner).getByRole("link", { name: new RegExp(cta) })).toHaveAttribute("href", `/${lang}/christmas`);
    const cards = within(banner).getAllByRole("link").filter((a) => !a.textContent?.includes(cta));
    expect(cards.map((a) => a.getAttribute("href"))).toEqual(SEED_HREFS.map((h) => `/${lang}${h}`));
  });
});

describe("golden: campaign list and detail pages", () => {
  const routes = (
    <Routes>
      <Route path="/:lang/campaigns" element={<CampaignsPage />} />
      <Route path="/:lang/campaigns/:slug" element={<CampaignDetailPage />} />
    </Routes>
  );

  it("vi list links to the detail page; detail renders one h1, the body and the CTA to /vi/christmas", async () => {
    mount(routes, "vi", "/vi/campaigns");
    const card = await screen.findByRole("link", { name: /Christmas 2026 Collection/ });
    expect(card).toHaveAttribute("href", "/vi/campaigns/christmas-2026");
    cleanup();

    mount(routes, "vi", "/vi/campaigns/christmas-2026");
    const h1 = await screen.findByRole("heading", { level: 1 });
    expect(h1).toHaveTextContent("Christmas 2026 Collection");
    expect(screen.getAllByRole("heading", { level: 1 })).toHaveLength(1);
    expect(screen.getByRole("heading", { level: 2, name: "Mùa lễ 2026 cùng TH Group" })).toBeInTheDocument();
    expect(screen.getAllByRole("link", { name: /Khám phá bộ sưu tập/ })[0]).toHaveAttribute("href", "/vi/christmas");
    await waitFor(() => expect(document.title).toBe("Christmas 2026 Collection | TH Group"));
    expect(document.querySelector('link[rel="canonical"]')).toHaveAttribute(
      "href",
      "https://thgfulfill.com/vi/campaigns/christmas-2026",
    );
  });

  it("en detail is indexable (available_locales has en) and serves the EN copy", async () => {
    mount(routes, "en", "/en/campaigns/christmas-2026");
    expect(await screen.findByRole("heading", { level: 2, name: "Holiday season 2026 with TH Group" })).toBeInTheDocument();
    expect(screen.getAllByRole("link", { name: /Explore Collection/ })[0]).toHaveAttribute("href", "/en/christmas");
    await waitFor(() =>
      expect(document.querySelector('meta[name="description"]')).toHaveAttribute(
        "content",
        "POD products ready for the holiday season: Christmas collection, best sellers, new arrivals and US fulfillment.",
      ),
    );
    expect(document.querySelector('meta[name="robots"]')?.getAttribute("content") ?? "").not.toContain("noindex");
  });
});
